def move(sign, price, base, pip, risk):
    x = sign * (price - base)
    return {'price': x, 'pips': x / pip, 'r': x / risk}

def checkpoint(qs, target, base, sign, pip, risk):
    if target >= CAP:
        return {'target_at': iso(target), 'state': 'not_elapsed_at_capture', 'movement': None}
    ix = bisect.bisect_right([q[0] for q in qs], target) - 1
    if ix < 0:
        return {'target_at': iso(target), 'state': 'missing_quote', 'movement': None}
    at, price = qs[ix]
